def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resource_positions = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    opponent_x, opponent_y = observation.get('opponent_position', (x, y))

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Find closest resource
    closest_resource = None
    min_dist = float('inf')
    for rx, ry in resource_positions:
        d = dist((rx, ry), (x, y))
        if d < min_dist:
            min_dist, closest_resource = d, (rx, ry)
    target_x, target_y = closest_resource if closest_resource else (x, y)

    # Choose move towards target/resource
    dx = dy = 0
    if target_x > x and (x + 1, y) not in obstacles and x + 1 < width:
        dx = 1
    elif target_x < x and (x - 1, y) not in obstacles and x - 1 >= 0:
        dx = -1
    elif target_y > y and (x, y + 1) not in obstacles and y + 1 < height:
        dy = 1
    elif target_y < y and (x, y - 1) not in obstacles and y - 1 >= 0:
        dy = -1
    else:
        # No progress possible towards target, try to move safely
        for nx, ny in [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]:
            if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles:
                dx, dy = nx - x, ny - y
                break
    return [dx, dy]
